import{_ as a}from"./chunks/daily-2026-08-10-authority-plane-cascade-containment-figure.B7bN8IO2.js";import{_ as r,C as n,o as i,c as o,E as s,a2 as d}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"多 Agent 恢复需要权威状态平面，而不是盲目重试","description":"","frontmatter":{"title":"多 Agent 恢复需要权威状态平面，而不是盲目重试","date":"2026-08-10","column":"industry-architecture","category":"daily","summary":"受控故障注入证据表明：重试可以恢复瞬态工具故障，但当同一坏状态仍被视为权威状态时，重试不能修复潜在语义污染；可靠遏制因此需要独立的状态权威与 Provenance 平面。","sources":["research/analysis/Q-20260810-02-authoritative-state-containment.md","research/reading/Q-20260810-02-trusted-state-cascade-containment.md"],"item_id":"Q-20260810-02","lifecycle":"Published","source_research_object":"research/analysis/Q-20260810-02-authoritative-state-containment.md","source_reading_result":"research/reading/Q-20260810-02-trusted-state-cascade-containment.md","cover":"/assets/covers/daily-2026-08-10-authority-plane-cascade-containment.webp","visualization":"/assets/covers/daily-2026-08-10-authority-plane-cascade-containment-figure.svg","visualization_decision":"Required — dedicated editorial Article Cover passes Cover Gate; explanatory Article Figure retained separately","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/industry/2026-08-10-authority-plane-cascade-containment.md","filePath":"zh/industry/2026-08-10-authority-plane-cascade-containment.md","lastUpdated":1786455299000}'),c={name:"zh/industry/2026-08-10-authority-plane-cascade-containment.md"};function l(h,e,u,p,m,g){const t=n("ArticleCover");return i(),o("div",null,[s(t,{image:"/assets/covers/daily-2026-08-10-authority-plane-cascade-containment.webp",kicker:"行业架构 · 每日研究",title:"多 Agent 恢复需要权威状态平面，而不是盲目重试",summary:"受控故障注入证据表明：重试可以恢复瞬态工具故障，但当同一坏状态仍被视为权威状态时，重试不能修复潜在语义污染；可靠遏制因此需要独立的状态权威与 Provenance 平面。",version:"Q-20260810-02",status:"Daily Runtime V5 · 2026-08-10",languageHref:"/en/industry/2026-08-10-authority-plane-cascade-containment",languageLabel:"English"}),e[0]||(e[0]=d('<h1 id="多-agent-恢复需要权威状态平面-而不是盲目重试" tabindex="-1">多 Agent 恢复需要权威状态平面，而不是盲目重试 <a class="header-anchor" href="#多-agent-恢复需要权威状态平面-而不是盲目重试" aria-label="Permalink to &quot;多 Agent 恢复需要权威状态平面，而不是盲目重试&quot;">​</a></h1><p>多 Agent 工作流发生故障时，“重试”和“修复”并不是同一件事。瞬态工具故障可以通过再次执行恢复可用性；如果每一次新尝试仍然消费同一份已经污染的状态，那么重试不会产生语义修复。</p><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p><strong>核心判断是：语义级恢复需要独立的 Authority Plane，明确哪些状态已经接受、哪些已经过期、隔离或被替代。</strong> Agent 可以负责诊断、比较、生成修复方案，但不应该让同一个推理上下文同时承担“判断真相”和“决定修复规则”两种角色，尤其当上下文本身可能已经被污染时。</p><p>本次完成的 Reading Result 以 OrchestraBench 为受控证据。它最强的 LLM 遏制条件明确提供 Trusted Upstream State；去掉这个信号后，Latent Recovery 明显下降到接近基线。因此可以复用的结论是 <strong>Trusted-state Reconciliation</strong>，而不是“LLM 可以自主自愈多 Agent 级联故障”。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>Production 只消费同日 Research Object <code>Q-20260810-02</code>，并仅使用已完成 Reading Result 核对引用和证据边界。一手来源是 OrchestraBench 预印本。</p><ul><li>arXiv：<a href="https://arxiv.org/abs/2608.05263" target="_blank" rel="noreferrer">https://arxiv.org/abs/2608.05263</a></li><li>全文：<a href="https://arxiv.org/html/2608.05263v1" target="_blank" rel="noreferrer">https://arxiv.org/html/2608.05263v1</a></li></ul><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>论文将瞬态 Tool Fault 与 Latent Semantic/Context Fault 分开评估。在受控分阶段计算中，Blind Retry 能够恢复可重试的工具故障；对于上下文污染、冲突输出等潜在语义故障，如果底层坏状态仍然存在，重试只是在重新传播同一个错误。</p><p>深度实验进一步显示，Latent Fault 会随着流水线加深扩大 Cascade Radius。更关键的是，Policy-conditioned LLM 条件给 Router 显式提供 Trusted Upstream Value，并允许它发现和纠正异常；去掉 Trusted Upstream 的消融后，Latent Recovery 明显下降。论文作者也明确提醒，这属于 Trusted-state Self-correction Probe，而不是 Autonomous Routing 的生产部署估计。</p><p><img src="'+a+'" alt="权威状态平面遏制机制图"></p><p><em>图 1：Trusted State 与独立 Authority Plane 共同限制潜在坏状态继续向下游级联。来源：Research Center 基于文中引用的一手资料综合绘制。</em></p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>恢复机制</th><th>改变了什么</th><th>最适合</th><th>语义污染风险</th><th>证据状态</th></tr></thead><tbody><tr><td>Blind Retry</td><td>基本保留原状态，重新执行</td><td>瞬态/可重试工具故障</td><td>坏状态仍是权威时风险高</td><td>OrchestraBench 基线机制</td></tr><tr><td>无 Trusted Upstream 的 LLM Repair</td><td>增加模型推理，但没有独立 Truth Signal</td><td>某些诊断可能改善</td><td>模型必须从可能污染的上下文中推断真相</td><td>消融结果在测试结构中接近基线</td></tr><tr><td>Trusted-state Repair</td><td>增加外部正确性/参考信号</td><td>受控实验中的潜在语义修复</td><td>Authority Signal 有效时显著降低</td><td>论文报告的强恢复条件</td></tr><tr><td>Authority-plane Reconciliation</td><td>Research Center 架构方案：版本化 Provenance、Accepted State、Invalidation 与 Selective Recompute</td><td>长生命周期生产工作流</td><td>取决于权威信号质量和冲突治理</td><td>架构推论，不是论文实测结果</td></tr></tbody></table><p>前三行对应论文和 Reading Result；第四行是 Research Center 的架构综合。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>可靠编排需要把 <strong>Reasoning Plane</strong> 和 <strong>Authority Plane</strong> 分开。Agent 可以解释、比较、规划和修复，但“哪一版状态是真正被接受的”应通过独立控制面表示，例如 Versioned Checkpoint、经过验证的 Business Fact、已批准的人工决定、Immutable Event Log Position，或者其他带明确 Provenance 的状态源。</p><p>这也要求把 Retry Policy 和 Semantic Repair Policy 分开。Transport Retry 解决的是“同一个操作再做一次能否成功”；Semantic Repair 解决的是“哪一份状态错了、哪一份状态才有权威、哪些下游产物需要失效”。两者混在一起，就会出现对污染上下文反复重算却无法真正修复的问题。</p><p>在分支工作流中，Cascade Impact 也不能只用线性距离衡量。生产系统应通过 Provenance Edge 记录每个下游产物消费了哪一版上游状态，恢复时才能只失效受影响的 Descendant，而不是重跑整个图。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对数字员工，应为长期任务保留权威工作状态 Checkpoint，尤其是人工审批和外部验证过的 Business Fact。发现语义不一致后，应先回到 Trusted Checkpoint 完成 Reconciliation，再重跑下游步骤。</p><p>对 CodeFlowMu，应给 Workflow Node 增加显式 State Version 与 Provenance 字段，并要求下游 Output 声明自己消费的 Upstream Version。Transient Tool/Transport Failure 的 Retry Policy 与 Semantic/Context Failure 的 Repair Policy 应彻底分开，同时记录 Invalidated Descendant，使恢复范围可观察。</p><p>对 TMPA，受控 Benchmark 可以作为 Evidence/Custody/Provenance 研究输入，但不能把一个 Benchmark 的 Trusted-state Probe 直接升级为协议强制要求。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>OrchestraBench 的核心实验是受控机制探针，不是完整企业级多 Agent 部署测量。部分领域验证只是给相同计算结构换了业务语义，并非真正的端到端业务系统。最强遏制条件具有信息优势，因为 Trusted State 被显式提供。真实生产环境中的权威信号本身也可能过期、冲突或被污染，因此 Authority Plane 同样需要自己的治理机制。</p><h2 id="后续工作" tabindex="-1">后续工作 <a class="header-anchor" href="#后续工作" aria-label="Permalink to &quot;后续工作&quot;">​</a></h2><p>下一步应继续回答：不同数字员工岗位中什么证据可以成为 Authoritative State；多个权威 Checkpoint 冲突时如何裁决；Provenance 如何覆盖 Branching DAG、异步工作与补偿流程；以及 Attribution + Repair 的成本与 Rollback、人工升级相比是否可接受。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>题图位于文章头部，以受控屏障表现权威状态平面对污染级联的遏制；嵌入“观察”部分的机制图用于说明 Trusted State、Authority Plane 与下游级联之间的关系。两种视觉角色使用不同资产；未使用厂商原图，也未构造无来源数值。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>OrchestraBench，arXiv 预印本 <code>2608.05263</code>：<a href="https://arxiv.org/abs/2608.05263" target="_blank" rel="noreferrer">https://arxiv.org/abs/2608.05263</a></li><li>OrchestraBench 全文：<a href="https://arxiv.org/html/2608.05263v1" target="_blank" rel="noreferrer">https://arxiv.org/html/2608.05263v1</a></li><li>Research Center Research Object：<code>research/analysis/Q-20260810-02-authoritative-state-containment.md</code></li><li>Research Center Reading Result：<code>research/reading/Q-20260810-02-trusted-state-cascade-containment.md</code></li></ol><blockquote><p>Editing status：已发布。Trusted-state 假设、消融解释、Retry/Repair 区分、局限与双语证据边界均已检查。</p></blockquote>',33))])}const R=r(c,[["render",l]]);export{v as __pageData,R as default};
